@answer jsEval
const adjacency = {};
const addEdge = (a, b) => {
  if (!adjacency[a]) adjacency[a] = [];
  if (!adjacency[b]) adjacency[b] = [];
  adjacency[a].push(b);
  adjacency[b].push(a);
};
$facts.edges.forEach(([a, b]) => addEdge(a, b));
const start = $largest;
const goal = $facts.target;
const visited = new Set([start]);
const queue = [start];
let found = start === goal;
while (queue.length > 0 && !found) {
  const node = queue.shift();
  const neighbors = adjacency[node] || [];
  for (const neighbor of neighbors) {
    if (!visited.has(neighbor)) {
      if (neighbor === goal) {
        found = true;
        break;
      }
      visited.add(neighbor);
      queue.push(neighbor);
    }
  }
}
return found ? "Yes, a path connects " + start + " to " + goal + "." : "No, no path connects " + start + " to " + goal + ".";
